CREATE TABLE daily_sales (
    store_id   integer NOT NULL,
    sale_date  date    NOT NULL,
    amount     numeric(12,2) NOT NULL
);

INSERT INTO daily_sales (store_id, sale_date, amount)
VALUES (1, '2026-10-15', 5000)
