CREATE TABLE customers (
    customer_id  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email        text NOT NULL,
    full_name    text NOT NULL,
    deleted_at   timestamptz
);

CREATE UNIQUE INDEX customers_email_active_uk
    ON customers (email)
    WHERE deleted_at IS NULL;

